/**  * Environment configuration loader & validator.  *  * Responsibilities:  *   - Load `.env` for local development (no-op on serverless platforms that  *     inject env vars directly).  *   - Validate required variables and fail fast with a clear message.  *   - Apply defaults and type coercion.  *   - Expose a single, frozen `config` object to the rest of the app.  *  * Design notes:  *   - This module has NO dependency on the logger (which itself depends on this  *     module) to avoid a circular import.  *   - `process.env` access is guarded so the module does not hard-crash in  *     runtimes where `process` is unavailable; deployment adapters can inject  *     values before import if needed.  *   - Deployment/business logic must import from here rather than reading  *     `process.env` directly, keeping configuration in one place.  */ import dotenv from 'dotenv'; // Load a local .env file when present. On Vercel/Cloudflare the platform // injects environment variables, so a missing .env file is expected there. dotenv.config(); const rawEnv = typeof process !== 'undefined' && process.env ? process.env : {}; /**  * @typedef {Object} EnvVarSpec  * @property {boolean} [required]  Fail startup if missing/empty.  * @property {string}  [default]   Value used when unset.  * @property {boolean} [secret]    Redact value from any diagnostic output.  * @property {(raw: string) => unknown} [transform] Coerce the raw string value.  * @property {string}  [description]  */ const toNumber = (value) => {   const n = Number(value);   if (Number.isNaN(n)) {     throw new Error(`expected a number but received "${value}"`);   }   return n; }; /**  * Declarative schema for every environment variable the backend understands.  * Add new variables here (and to .env.example) as later phases need them.  *  * NOTE: Provider secrets are intentionally `required: false` for Phase 1 so the  * foundation boots without any provider being wired up yet. Flip `required` to  * `true` in the phase that actually depends on the variable.  *  * @type {Record<string, EnvVarSpec>}  */ const schema = {   NODE_ENV: { default: 'development', description: 'development | production | test' },   PORT: { default: '8080', transform: toNumber, description: 'Port for the Node server shell.' },   HOST: { default: '0.0.0.0', description: 'Bind host for the Node server shell.' },   CORS_ORIGIN: { default: '*', description: 'Comma-separated allowed origins or "*".' },   ANILIST_API_URL: { default: 'https://graphql.anilist.co' },   JIKAN_API_URL: { default: 'https://api.jikan.moe/v4' },   TMDB_API_URL: { default: 'https://api.themoviedb.org/3' },   MEGAPLAY_API_URL: { default: 'https://megaplay.buzz' },   TMDB_API_KEY: { required: false, secret: true, default: '' },   SUPABASE_URL: { required: false, default: '' },   SUPABASE_ANON_KEY: { required: false, secret: true, default: '' },   // SECRET - server-side only; preferred over the anon key for L2 cache access   // because it bypasses RLS. Never exposed to the frontend or logs.   SUPABASE_SERVICE_ROLE_KEY: { required: false, secret: true, default: '' },   CACHE_DEFAULT_TTL_SECONDS: { default: '300', transform: toNumber },   REQUEST_TIMEOUT_MS: { default: '10000', transform: toNumber },   LOG_LEVEL: { default: 'info', description: 'debug | info | warn | error' }, }; /**  * Build the validated config object from the schema.  * Collects ALL problems before throwing so the operator sees everything at once.  * @returns {Readonly<Record<string, unknown>>}  */ function loadConfig() {   /** @type {Record<string, unknown>} */   const config = {};   /** @type {string[]} */   const errors = [];   for (const [key, spec] of Object.entries(schema)) {     const rawValue = rawEnv[key];     const hasValue = rawValue !== undefined && rawValue !== '';     if (!hasValue) {       if (spec.required) {         errors.push(`  - ${key} is required but was not set${spec.description ? ` (${spec.description})` : ''}`);         continue;       }       config[key] = spec.default !== undefined ? coerce(key, spec, spec.default, errors) : undefined;       continue;     }     config[key] = coerce(key, spec, rawValue, errors);   }   if (errors.length > 0) {     throw new Error(       'Invalid environment configuration:
' +         errors.join('
') +         '

See .env.example for the full list of supported variables.',     );   }   // Convenience booleans derived from NODE_ENV.   config.IS_PRODUCTION = config.NODE_ENV === 'production';   config.IS_TEST = config.NODE_ENV === 'test';   return Object.freeze(config); } /**  * @param {string} key  * @param {EnvVarSpec} spec  * @param {string} value  * @param {string[]} errors  */ function coerce(key, spec, value, errors) {   if (!spec.transform) return value;   try {     return spec.transform(value);   } catch (err) {     errors.push(`  - ${key}: ${err instanceof Error ? err.message : String(err)}`);     return undefined;   } } /**  * Validated, frozen application configuration.  * @type {Readonly<Record<string, any>>}  */ export const config = loadConfig(); /**  * Return a copy of the config with secret values redacted, suitable for logs.  * @returns {Record<string, unknown>}  */ export function getRedactedConfig() {   const redacted = { ...config };   for (const [key, spec] of Object.entries(schema)) {     if (spec.secret && redacted[key]) redacted[key] = '***redacted***';   }   return redacted; }

/**  * Normalizer tests - canonical anime model + defensive behavior.  *  * All fixtures are mocked; no live API calls.  */ process.env.LOG_LEVEL = 'error'; import test from 'node:test'; import assert from 'node:assert/strict'; const { normalizeAnilistAnime, createBaseAnime, normalizeAnilistTitle, normalizeAnilistImages, normalizeAnilistPage, normalizeAnilistRelations } = await import('../src/normalizers/anime.normalizer.js'); const { normalizeAnilistRelation } = await import('../src/normalizers/anime.normalizer.js'); const { cleanDescription } = await import('../src/utils/html.js'); const { ProviderError } = await import('../src/errors/index.js'); /** Realistic full AniList Media fixture. */ const fullMedia = {   id: 1,   idMal: 1,   title: { romaji: 'Cowboy Bebop', english: 'Cowboy Bebop', native: 'カウボーイビバップ', userPreferred: 'Cowboy Bebop' },   description: 'In the year 2071, humanity has colonized<br>several of the planets and moons of the solar system. <i>Bounty hunters</i> roam the galaxy.',   coverImage: { extraLarge: 'https://img.example/xl.jpg', large: 'https://img.example/l.jpg', medium: 'https://img.example/m.jpg' },   bannerImage: 'https://img.example/banner.jpg',   type: 'ANIME',   format: 'TV',   status: 'FINISHED',   episodes: 26,   duration: 24,   season: 'SPRING',   seasonYear: 1998,   genres: ['Action', 'Sci-Fi'],   synonyms: ['Kaubōi Bibappu'],   studios: { nodes: [{ name: 'Sunrise' }] },   startDate: { year: 1998, month: 4, day: 3 },   endDate: { year: 1999, month: 4, day: 24 },   averageScore: 86,   popularity: 200000, }; test('valid AniList object -> full canonical shape with id === anilistId', () => {   const anime = normalizeAnilistAnime(fullMedia);   assert.equal(anime.id, 1);   assert.equal(anime.anilistId, 1);   assert.equal(anime.id, anime.anilistId);   assert.equal(anime.malId, 1);   assert.deepEqual(anime.title, {     romaji: 'Cowboy Bebop',     english: 'Cowboy Bebop',     native: 'カウボーイビバップ',     userPreferred: 'Cowboy Bebop',   });   assert.deepEqual(anime.images, {     poster: 'https://img.example/xl.jpg',     cover: 'https://img.example/l.jpg',     banner: 'https://img.example/banner.jpg',   });   assert.equal(anime.type, 'ANIME');   assert.equal(anime.format, 'TV');   assert.equal(anime.status, 'FINISHED');   assert.equal(anime.episodes, 26);   assert.equal(anime.duration, 24);   assert.equal(anime.season, 'SPRING');   assert.equal(anime.seasonYear, 1998);   assert.deepEqual(anime.genres, ['Action', 'Sci-Fi']);   assert.deepEqual(anime.studios, ['Sunrise']);   assert.deepEqual(anime.synonyms, ['Kaubōi Bibappu']);   assert.equal(anime.startDate, '1998-04-03');   assert.equal(anime.endDate, '1999-04-24');   assert.equal(anime.averageScore, 86);   assert.equal(anime.popularity, 200000);   assert.deepEqual(anime.source, { anilist: true, jikan: false, tmdb: false });   // No undefined anywhere in the serialized model.   assert.ok(!JSON.stringify(anime).includes('undefined')); }); test('missing MAL ID -> malId null, anilistId preserved', () => {   const anime = normalizeAnilistAnime({ ...fullMedia, idMal: null });   assert.equal(anime.malId, null);   assert.equal(anime.anilistId, 1);   assert.equal(anime.id, 1); }); test('malId never becomes the anilistId / id', () => {   const anime = normalizeAnilistAnime({ ...fullMedia, id: 500, idMal: 999 });   assert.equal(anime.id, 500);   assert.equal(anime.anilistId, 500);   assert.equal(anime.malId, 999);   assert.notEqual(anime.id, 999); }); test('missing description -> null, no throw', () => {   const anime = normalizeAnilistAnime({ ...fullMedia, description: null });   assert.equal(anime.description, null); }); test('missing images -> all image fields null, no throw', () => {   const anime = normalizeAnilistAnime({ ...fullMedia, coverImage: null, bannerImage: null });   assert.deepEqual(anime.images, { poster: null, cover: null, banner: null }); }); test('banner is null unless AniList genuinely provides one (poster is never faked as banner)', () => {   const anime = normalizeAnilistAnime({ ...fullMedia, bannerImage: null });   assert.equal(anime.images.banner, null);   assert.notEqual(anime.images.banner, anime.images.poster); }); test('missing title variants -> nulls; userPreferred falls back to existing fields', () => {   const anime = normalizeAnilistAnime({ ...fullMedia, title: {} });   assert.deepEqual(anime.title, { romaji: null, english: null, native: null, userPreferred: null });   const romajiOnly = normalizeAnilistTitle({ romaji: 'Romaji Only' });   assert.equal(romajiOnly.userPreferred, 'Romaji Only');   const englishAndRomaji = normalizeAnilistTitle({ romaji: 'Romaji', english: 'English' });   assert.equal(englishAndRomaji.userPreferred, 'English'); }); test('userPreferred is never overwritten when present', () => {   const t = normalizeAnilistTitle({ romaji: 'A', english: 'B', userPreferred: 'C' });   assert.equal(t.userPreferred, 'C'); }); test('empty arrays and missing list fields normalize to []', () => {   const anime = normalizeAnilistAnime({     ...fullMedia,     genres: [],     synonyms: null,     studios: null,   });   assert.deepEqual(anime.genres, []);   assert.deepEqual(anime.synonyms, []);   assert.deepEqual(anime.studios, []); }); test('null optional fields remain valid (season, dates, scores, duration)', () => {   const anime = normalizeAnilistAnime({     ...fullMedia,     season: null,     seasonYear: null,     duration: null,     startDate: null,     endDate: null,     averageScore: null,     popularity: null,     episodes: null,   });   assert.equal(anime.season, null);   assert.equal(anime.seasonYear, null);   assert.equal(anime.duration, null);   assert.equal(anime.startDate, null);   assert.equal(anime.endDate, null);   assert.equal(anime.averageScore, null);   assert.equal(anime.popularity, null);   assert.equal(anime.episodes, null); }); test('partial fuzzy dates stay honest (year only -> "YYYY", year+month -> "YYYY-MM")', () => {   const anime = normalizeAnilistAnime({     ...fullMedia,     startDate: { year: 2020 },     endDate: { year: 2021, month: 7 },   });   assert.equal(anime.startDate, '2020');   assert.equal(anime.endDate, '2021-07'); }); test('description HTML cleanup: tags stripped, structure preserved, entities decoded', () => {   const anime = normalizeAnilistAnime({ ...fullMedia });   assert.equal(anime.description.includes('<'), false);   assert.equal(anime.description.includes('>'), false);   assert.ok(anime.description.includes('
'));   assert.ok(anime.description.includes('Bounty hunters')); }); test('cleanDescription utility behavior', () => {   assert.equal(cleanDescription('<b>Hello</b> & <i>world</i>'), 'Hello & world');   assert.equal(cleanDescription('Line one<br>Line two</p><p>Line three'), 'Line one
Line two
Line three');   assert.equal(cleanDescription('~!spoiler text!~ stays'), 'spoiler text stays');   assert.equal(cleanDescription('&#039;quoted&#39; "text"'), "'quoted' "text"");   assert.equal(cleanDescription(null), null);   assert.equal(cleanDescription(undefined), null);   assert.equal(cleanDescription('   '), null); }); test('relations included when present; unusable relation nodes dropped', () => {   const withRelations = normalizeAnilistAnime({     ...fullMedia,     relations: {       nodes: [         { id: 2, idMal: 2, relationType: 'SEQUEL', type: 'ANIME', format: 'TV', title: { romaji: 'Sequel' }, coverImage: { large: 'https://img.example/2.jpg' } },         { idMal: 3, relationType: 'SIDE_STORY' }, // missing id -> dropped         null, // junk node -> dropped       ],     },   });   assert.equal(withRelations.relations.length, 1);   assert.equal(withRelations.relations[0].anilistId, 2);   assert.equal(withRelations.relations[0].malId, 2);   assert.equal(withRelations.relations[0].relationType, 'SEQUEL'); }); test('no relations in payload -> relations: []', () => {   const anime = normalizeAnilistAnime({ ...fullMedia });   assert.deepEqual(anime.relations, []); }); test('malformed payload (null/missing id) -> ProviderError, never silent garbage', () => {   assert.throws(() => normalizeAnilistAnime(null), ProviderError);   assert.throws(() => normalizeAnilistAnime({}), ProviderError);   assert.throws(() => normalizeAnilistAnime({ idMal: 5 }), ProviderError);   assert.throws(() => normalizeAnilistAnime([1, 2]), ProviderError); }); test('normalizeAnilistPage builds stable page shape and drops junk entries', () => {   const page = normalizeAnilistPage({     pageInfo: { total: 2, currentPage: 1, lastPage: 1, hasNextPage: false, perPage: 20 },     media: [       { id: 10, idMal: 10, title: { english: 'A' }, format: 'TV', status: 'FINISHED', coverImage: { large: 'https://img.example/a.jpg' } },       { idMal: 11 }, // missing id -> dropped     ],   });   assert.equal(page.pageInfo.total, 2);   assert.equal(page.pageInfo.hasNextPage, false);   assert.equal(page.results.length, 1);   assert.equal(page.results[0].anilistId, 10); }); test('createBaseAnime yields the canonical skeleton', () => {   const anime = createBaseAnime({ anilistId: 123, malId: 456 });   assert.equal(anime.id, 123);   assert.equal(anime.malId, 456);   assert.deepEqual(anime.title, { romaji: null, english: null, native: null, userPreferred: null });   assert.deepEqual(anime.images, { poster: null, cover: null, banner: null });   assert.deepEqual(anime.genres, []);   assert.deepEqual(anime.relations, []); });
